            new() { Id = 2, TrackingNumber = "TRK-100202", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.Now.AddDays(-10), EstimatedDelivery = DateTime.Now.AddDays(-1), CustomerEmail = "bob@example.com", Description = "Furniture - Office desk set" },
            new() { Id = 3, TrackingNumber = "TRK-100203", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = ShipmentStatus.Pending, ShippedDate = DateTime.Now, EstimatedDelivery = DateTime.Now.AddDays(7), CustomerEmail = "carol@example.com", Description = "Automotive parts - Brake system" },
