@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h3 class="mb-4">Dispatcher Dashboard</h3>

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped Date</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in shipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <div class="d-flex gap-2">
                                <select class="form-select form-select-sm" style="width: auto;"
                                        @onchange="(e) => OnStatusSelected(shipment.Id, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status" selected="@(status == shipment.Status)">@status</option>
                                    }
                                </select>
                                <button class="btn btn-sm btn-primary" @onclick="() => UpdateStatus(shipment.Id)">Update</button>
                            </div>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Shipment>? shipments;
    private Dictionary<int, ShipmentStatus> pendingUpdates = new();

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void OnStatusSelected(int shipmentId, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            pendingUpdates[shipmentId] = status;
        }
    }

    private async Task UpdateStatus(int shipmentId)
    {
        if (pendingUpdates.TryGetValue(shipmentId, out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipmentId, newStatus);
            shipments = await ShipmentService.GetAllShipmentsAsync();
            pendingUpdates.Remove(shipmentId);
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-warning text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Pending => "bg-secondary",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h3 class="mb-4">Track Your Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-100201)"
                   @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment">Track</button>
        </div>
    </div>
</div>

@if (searched)
{
    @if (shipment != null)
    {
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Shipment Details — @shipment.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Tracking Number</dt>
                            <dd>@shipment.TrackingNumber</dd>

                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>

                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>

                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Status</dt>
                            <dd><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>

                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

                            <dt>Estimated Delivery</dt>
                            <dd>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
                        </dl>
                    </div>
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment was found with tracking number "<strong>@searchedNumber</strong>". Please check the number and try again.
        </div>
    }
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await SearchShipment();
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-warning text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Pending => "bg-secondary",
        _ => "bg-secondary"
    };
}

@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h3 class="mb-4">Dispatcher Dashboard</h3>

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped Date</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in shipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <div class="d-flex gap-2">
                                <select class="form-select form-select-sm" style="width: auto;"
                                        @onchange="(e) => OnStatusSelected(shipment.Id, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status" selected="@(status == shipment.Status)">@status</option>
                                    }
                                </select>
                                <button class="btn btn-sm btn-primary" @onclick="() => UpdateStatus(shipment.Id)">Update</button>
                            </div>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Shipment>? shipments;
    private Dictionary<int, ShipmentStatus> pendingUpdates = new();

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void OnStatusSelected(int shipmentId, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            pendingUpdates[shipmentId] = status;
        }
    }

    private async Task UpdateStatus(int shipmentId)
    {
        if (pendingUpdates.TryGetValue(shipmentId, out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipmentId, newStatus);
            shipments = await ShipmentService.GetAllShipmentsAsync();
            pendingUpdates.Remove(shipmentId);
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-warning text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Pending => "bg-secondary",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h3 class="mb-4">Track Your Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-100201)"
                   @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment">Track</button>
        </div>
    </div>
</div>

@if (searched)
{
    @if (shipment != null)
    {
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Shipment Details — @shipment.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Tracking Number</dt>
                            <dd>@shipment.TrackingNumber</dd>

                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>

                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>

                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Status</dt>
                            <dd><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>

                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

                            <dt>Estimated Delivery</dt>
                            <dd>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
                        </dl>
                    </div>
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment was found with tracking number "<strong>@searchedNumber</strong>". Please check the number and try again.
        </div>
    }
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await SearchShipment();
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-warning text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Pending => "bg-secondary",
        _ => "bg-secondary"
    };
}

